"""Generate Unicode 17 full-fold exceptions from pinned CPython 3.15.

No downloads, locale tailoring, normalization, or new Go module dependencies.
--check checks deterministic source; --oracle writes every valid Unicode scalar
and its Python full-fold UTF-8 bytes for an exact independent Go comparison.
"""
import argparse
import hashlib
from pathlib import Path
import struct
import subprocess
import sys
import unicodedata

assert sys.version_info[:2] == (3, 15), "CPython 3.15 is required"
assert unicodedata.unidata_version == "17.0.0", "Unicode 17.0.0 is required"

parser = argparse.ArgumentParser()
parser.add_argument("--check", action="store_true")
parser.add_argument("--oracle", type=Path)
args = parser.parse_args()
destination = Path(__file__).resolve().parents[1] / "catalog_fold_generated.go"
exceptions = []
digest = hashlib.sha256()
oracle = args.oracle.open("wb") if args.oracle else None
count = 0
try:
    for rune in range(0x110000):
        if 0xD800 <= rune <= 0xDFFF:
            continue
        character = chr(rune)
        folded = character.casefold()
        if folded != character.lower() or len(character.lower()) != 1:
            value = '"' + ''.join('\\U%08x' % ord(c) for c in folded) + '"'
            exceptions.append("\t0x%04x: %s," % (rune, value))
        encoded = folded.encode("utf-8")
        record = struct.pack(">II", rune, len(encoded)) + encoded
        digest.update(record)
        if oracle:
            oracle.write(record)
        count += 1
finally:
    if oracle:
        oracle.close()
source = '''// Code generated by testdata/generate_catalog_fold.py using CPython 3.15
// Unicode 17.0.0 str.casefold(); DO NOT EDIT.
package workspace

const catalogFoldUnicodeVersion = "17.0.0"
const catalogFoldScalarCount = %d
const catalogFoldOracleSHA256 = "%s"

var catalogFoldExceptions = map[rune]string{
%s
}
''' % (count, digest.hexdigest(), '\n'.join(exceptions))
gofmt = Path(__file__).resolve().parents[4] / "artifacts/2026-10-25-slice-01/q01-cache/go1.27.3/go/bin/gofmt.exe"
source = subprocess.run([str(gofmt)], input=source.encode("utf-8"), stdout=subprocess.PIPE, check=True).stdout.decode("utf-8")
if args.check:
    assert destination.read_text(encoding="utf-8") == source, "catalog fold generated source drift"
else:
    destination.write_text(source, encoding="utf-8", newline="\n")
print("Unicode17 full-fold scalars=%d exceptions=%d sha256=%s" % (count, len(exceptions), digest.hexdigest()))
